// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testRegression_property() public {
        // The reference owner() returns address(this) because Ownable constructor sets owner to msg.sender (which is this test contract).
        // The mutant owner() returns address(0) always.
        address ownerInContract = c.owner();
        assertTrue(ownerInContract == address(this), "owner() should return the test contract address");
    }
}

