pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testRegression_property() public {
        // After setUp, owner() returns address(this) in reference, address(0) in mutant
        // Attempt to call setCaller (onlyOwner) from the test contract
        bool ok;
        try c.setCaller(address(0x123)) {
            ok = true;
        } catch {
            ok = false;
        }
        // Reference: setCaller succeeds (owner == msg.sender == address(this))
        // Mutant: setCaller reverts (owner() returns address(0) != msg.sender)
        assertTrue(ok, "setCaller should succeed in reference but revert in mutant");
    }
}

