pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testRegression_property() public {
        // Owner address is address(this) from setUp
        address originalOwner = c.owner();

        // Call transferOwnership(address(0)) — buggy version allows this, reference reverts
        c.transferOwnership(address(0));

        // Now call allowance as the specified entry point
        c.allowance(address(this), address(0));

        // After this sequence, reference contract rejects the transferOwnership call,
        // so owner() stays originalOwner. Buggy version accepts it, owner() becomes address(0).
        // Wrap the assertion: we check that owner() is still originalOwner.
        // On reference: true; on bug: false.
        assertTrue(c.owner() == originalOwner, "owner should remain unchanged");
    }
}

