pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testRegression_property() public {
        // Deployer is owner (address(this))
        address owner = address(this);

        // Owner tries to transfer ownership to zero address
        vm.prank(owner);
        // The reference will revert (require non-zero), the buggy will succeed
        // We don't check revert here; we just execute and observe state
        (bool ok, ) = address(c).call(abi.encodeWithSignature("transferOwnership(address)", address(0)));

        // Now call allowance (doesn't matter with what parameters)
        c.allowance(owner, address(1));

        // Check owner() value: reference should still be owner, buggy should be address(0)
        assertTrue(c.owner() == owner || c.owner() == address(0));
        // The reference always keeps owner; buggy changes to zero. So assert the correct behavior:
        // We know the test passes on reference (owner unchanged) and fails on buggy (owner becomes zero)
        assertTrue(c.owner() == owner);
    }
}

