pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testRegression_property() public {
        address ownerBefore = c.owner();

        // The reference requires newOwner != address(0), so this should revert
        // The buggy version requires newOwner == address(0), so this should succeed
        bool txSucceeded;
        try c.transferOwnership(address(0)) {
            txSucceeded = true;
        } catch {
            txSucceeded = false;
        }

        // Now call allowance (any call works to demonstrate divergence)
        c.allowance(address(this), address(0));

        address ownerAfter = c.owner();

        // On reference: transferOwnership(address(0)) reverts, so owner stays the same
        // On buggy version: transferOwnership(address(0)) succeeds, so owner becomes address(0)
        // This assertion passes on reference (ownerAfter == ownerBefore) and fails on buggy (ownerAfter != ownerBefore)
        assertTrue(ownerAfter == ownerBefore, "Owner should not change to zero");
    }
}

