pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testRegression_property() public {
        // The owner is the test contract (address(this)). 
        // The owner has 2 million tokens from the constructor.
        // The contract is deployed and the LiquidityHelper is created.
        // We need to trigger the _transfer path that involves the pair.
        // 1. Get the pair address and transfer from owner to pair directly (not via router).
        address pair = c.pairAddress();

        // 2. The owner transfers tokens to the pair (this triggers the "to == pairAddress" branch with swapping=false)
        uint256 transferAmount = 1000 * 1e18; // some tokens
        vm.prank(address(this));
        c.transfer(pair, transferAmount);

        // 3. Now, simulate a trade via router by pranking the router address and calling swapExactTokensForTokensSupportingFeeOnTransferTokens
        // However, the router address is hardcoded in C as a constant. We will use vm.startPrank on that address.
        address routerAddr = 0x10ED43C718714eb63d5aA57B78B54704E256024E;
        vm.startPrank(routerAddr);
        // Need USDT tokens at the contract C to swap? Actually we'll call a function that triggers the internal swap.
        // The contract C has no USDT by default, so the swap will fail due to insufficient liquidity.
        // Instead, we can observe a difference by checking the balance of the helper after the transfer.
        // The buggy balanceOf returns 0, so the helper's USDT balance after the swap will be 0.
        // Let's just check that the reference contract's helper has some tokens after transfer?
        // Actually simpler: after the transfer above, the reference contract C should have fee tokens (5% of transferAmount = 50 tokens).
        // The balanceOf in reference returns actual balance; buggy returns 0.
        // We can compare the balance of address(this) in the helper? No, helper is internal.
        // But we can check the balance of the C contract itself: c.balanceOf(address(c)).
        uint256 balRef = c.balanceOf(address(c));
        // In reference, after transfer, C has 50 tokens. In buggy, balanceOf returns 0, so 0 tokens.
        assertTrue(balRef == 50e18, "balanceOf should return 50e18 in reference but buggy returns 0");
        vm.stopPrank();
    }
}

