contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testRegression_property() public {
        // Owner transfers tokens to LP pair (non-whitelisted) to trigger swap and burnPair
        // The buggy balanceOf(pairAddress) returns 0, causing burnPair to revert
        // The reference balanceOf(pairAddress) returns the actual balance, so burnPair succeeds

        // First, set up the necessary state: set caller to owner, add liquidity etc.
        // We need to ensure the swap path works: transfer tokens from owner to pair

        address owner = address(this);
        address pair = c.pairAddress();

        // Transfer tokens from owner to pair (non-whitelisted) - this should trigger swap logic
        // In the reference, balanceOf(pair) returns >0, burnPair works
        // In the buggy, balanceOf(pair) returns 0, burnPair reverts

        uint256 initialBalance = c.balanceOf(owner);
        uint256 transferAmount = 1000 * 1e18;

        // Ensure whiteAddress[owner] is true (constructor sets it)
        // Ensure whiteAddress[address(this)] is true (constructor sets it)
        // Now transfer to pair
        vm.prank(owner);
        c.transfer(pair, transferAmount);

        // The reference should succeed, the buggy version might revert or behave differently
        // We check that the transfer actually happened
        bool success = c.balanceOf(pair) > 0;

        // In the reference, the transfer succeeds and pair has balance > 0
        // In the buggy version, the transfer might revert because burnPair fails
        // Since we can't distinguish revert vs success from outside, we check balanceOf
        // But the buggy balanceOf(pair) will return 0 always, so the assertion will fail
        assertTrue(success);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testRegression_property() public {
        // Set the caller (owner) to this contract
        // owner is this contract since new C(address(this)) set msg.sender = this
        // Deploy a simple address to act as pairAddress holder (we will mint to pairAddress)
        address pairAddr = address(0x123);

        // We need to set cfo so we can set whiteAddress and other controls
        // Since owner can set caller
        c.setCaller(address(this));

        // Make the pairAddress white-listed to allow transfers later
        c.setWhite(pairAddr, true);

        // Transfer some tokens to pairAddr so it has balance
        uint256 mintAmount = 1000 * 1e18;
        c.transfer(pairAddr, mintAmount);

        // Now call distributeTokenPeriodic to trigger the internal transfer and burnPair
        // This requires initTime to be less than block.timestamp (it starts at 0)
        vm.warp(1); // block.timestamp = 1 > 0

        // Get the balance of pairAddr before the call
        uint256 balanceBefore = c.balanceOf(pairAddr);

        // Call distributeTokenPeriodic
        c.distributeTokenPeriodic();

        // Get the balance of pairAddr after
        uint256 balanceAfter = c.balanceOf(pairAddr);

        // Assert: in reference, balance decreased (burnPair burned tokens), in bug balance stays same
        // For reference: balanceAfter < balanceBefore; for bug: balanceAfter == balanceBefore
        assertTrue(balanceAfter < balanceBefore);
    }
}

