        // Set the cfo to allow distributeTokenPeriodic to be called
        address cfo = address(0x1234);
        vm.prank(owner);
        c.setCaller(cfo);

        // Set distribute address so distributeTokenPeriodic doesn't revert
        address distAddr = address(0x5678);
        vm.prank(cfo);
        c.setDistributeAddress(distAddr);

        // Transfer tokens to a non-whitelisted address to trigger swap logic
        // The contract needs tokens in its own balance for distributeTokenPeriodic
        // We'll transfer from owner (who has all tokens) to a non-whitelisted address
        // This triggers the _transfer override which will call swapTokensForUSDT and then liquidityHelper.addLiquidity
        // After that, the contract should have some tokens from the fee

        // First, give the contract some ETH for swap fees (not needed for this test)

        // Transfer to a non-whitelisted address that is not the pair
        address nonWhitelisted = address(0x9999);
